"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["28643"],{31490(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cota_e_acao_afirmativa_derivaveis_juntas","status":422,"titulo":"As regras de aplicabilidade d\xe3o ao mesmo candidato uma cota da lei e uma a\xe7\xe3o afirmativa diferente da AC_PCD"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cota_e_acao_afirmativa_derivaveis_juntas","requisitos":["UNI-REQ-0142","UNI-REQ-0266"],"oQueAconteceu":["As modalidades de cada candidato n\xe3o s\xe3o escolhidas por ele: o sistema as\\ndefine a partir das respostas da inscri\xe7\xe3o, seguindo a **regra de\\naplicabilidade** de cada modalidade, que \xe9 congelada junto com a modalidade. A\\nmodalidade vale para o candidato quando alguma cl\xe1usula da regra dela \xe9\\nverdadeira, e o conjunto de modalidades do candidato \xe9 a uni\xe3o das modalidades\\naplic\xe1veis. Ao conferir essas regras para publicar, o sistema encontrou uma\\ncombina\xe7\xe3o de respostas que d\xe1 ao mesmo candidato uma **cota da Lei\\n12.711/2012** (`LI_*` ou `LB_*`) e uma **a\xe7\xe3o afirmativa** diferente da\\n`AC_PCD`. A mensagem nomeia a cota e a a\xe7\xe3o afirmativa do par.","Quem opta pelas cotas da lei \u2014 \xe9 egresso de escola p\xfablica e responde que\\ndeseja concorrer \xe0s vagas de escola p\xfablica \u2014 concorre \xe0s cotas e n\xe3o concorre\\na nenhuma a\xe7\xe3o afirmativa, **salvo a `AC_PCD`**: a pessoa com defici\xeancia que\\nopta pelas cotas e responde que deseja concorrer como pessoa com defici\xeancia\\ndisputa as vagas de pessoa com defici\xeancia da lei e tamb\xe9m a `AC_PCD`, ocupando\\numa \xfanica vaga. A `AC_PCD` \xe9 a \xfanica a\xe7\xe3o afirmativa que se soma \xe0s cotas da\\nlei na mesma inscri\xe7\xe3o; para as demais, a exclusividade continua valendo. A\\nregra da `AC_PCD` n\xe3o cita a op\xe7\xe3o pelas cotas da lei, e por isso n\xe3o \xe9\\nrecusada por esta confer\xeancia.","Publicado assim, o edital classificaria candidatos em vagas a que eles n\xe3o t\xeam\\ndireito ao mesmo tempo, e cada vaga ocupada dessa forma seria tirada de quem s\xf3\\ntem uma das vias. A confer\xeancia olha s\xf3 as regras, sem depender de inscri\xe7\xe3o\\nnenhuma: se existe uma resposta poss\xedvel que d\xea as duas modalidades, a\\npublica\xe7\xe3o \xe9 recusada.","Ofertar as duas no mesmo processo continua v\xe1lido. A exclusividade \xe9 por\\ninscri\xe7\xe3o, n\xe3o por oferta."],"comoResolver":["Corrija a regra de aplicabilidade da a\xe7\xe3o afirmativa diferente da `AC_PCD`\\nque a mensagem nomeia, para que ela recuse quem optou pelas cotas da lei, o que\\nas regras de cota exigem. A `AC_PCD` n\xe3o precisa dessa corre\xe7\xe3o: ela vale para\\na pessoa com defici\xeancia que deseja concorrer como tal, tenha ou n\xe3o optado\\npelas cotas da lei.","O item correspondente no checklist de conformidade do processo mostra a mesma\\npend\xeancia, o que permite conferir a corre\xe7\xe3o antes de tentar publicar de novo."],"ondeAparece":["Publica\xe7\xe3o de um processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);